iterations.reply:
Two notes on the files below:

- **Authority:** I added `aap:caps/http-client@0.1.0` to the world, because the approved extension needs it for the enrichment fetch.
- **Enrichment input:** `digest` has no field called "text", so I used `overview` as the query text. I percent-encode it into the URL.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch: result is deliberately ignored so output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&composed.overview)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!(
            "digest {}: {} entries ({} kept)",
            composed.date,
            composed.entries.len(),
            kept
        );
        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

